CREATE TABLE litebans_bans (id BIGINT AUTO_INCREMENT PRIMARY KEY, uuid VARCHAR(36), ip VARCHAR(45), reason VARCHAR(2048), banned_by_uuid VARCHAR(36), banned_by_name VARCHAR(128), removed_by_uuid VARCHAR(36), removed_by_name VARCHAR(128), removed_by_reason VARCHAR(2048), removed_by_date TIMESTAMP, "time" BIGINT, "until" BIGINT, template SMALLINT DEFAULT 255, server_scope VARCHAR(32), server_origin VARCHAR(32), silent BOOLEAN, ipban BOOLEAN, ipban_wildcard BOOLEAN DEFAULT FALSE, active BOOLEAN);
CREATE TABLE litebans_mutes (id BIGINT AUTO_INCREMENT PRIMARY KEY, uuid VARCHAR(36), ip VARCHAR(45), reason VARCHAR(2048), banned_by_uuid VARCHAR(36), banned_by_name VARCHAR(128), removed_by_uuid VARCHAR(36), removed_by_name VARCHAR(128), removed_by_reason VARCHAR(2048), removed_by_date TIMESTAMP, "time" BIGINT, "until" BIGINT, template SMALLINT DEFAULT 255, server_scope VARCHAR(32), server_origin VARCHAR(32), silent BOOLEAN, ipban BOOLEAN, ipban_wildcard BOOLEAN DEFAULT FALSE, active BOOLEAN);
CREATE TABLE litebans_warnings (id BIGINT AUTO_INCREMENT PRIMARY KEY, uuid VARCHAR(36), ip VARCHAR(45), reason VARCHAR(2048), banned_by_uuid VARCHAR(36), banned_by_name VARCHAR(128), removed_by_uuid VARCHAR(36), removed_by_name VARCHAR(128), removed_by_reason VARCHAR(2048), removed_by_date TIMESTAMP, "time" BIGINT, "until" BIGINT, template SMALLINT DEFAULT 255, server_scope VARCHAR(32), server_origin VARCHAR(32), silent BOOLEAN, ipban BOOLEAN, ipban_wildcard BOOLEAN DEFAULT FALSE, active BOOLEAN, warned BOOLEAN);
CREATE TABLE litebans_kicks (id BIGINT AUTO_INCREMENT PRIMARY KEY, uuid VARCHAR(36), ip VARCHAR(45), reason VARCHAR(2048), banned_by_uuid VARCHAR(36), banned_by_name VARCHAR(128), "time" BIGINT, "until" BIGINT, template SMALLINT DEFAULT 255, server_scope VARCHAR(32), server_origin VARCHAR(32), silent BOOLEAN, ipban BOOLEAN, ipban_wildcard BOOLEAN DEFAULT FALSE, active BOOLEAN);
